-- 024: Ampliar dos lecciones fundamentales de N5 en la zona de aprendizaje.
-- Rodrigo pidió más ejemplos y explicaciones ANTES de los ejercicios para
-- これ・それ・あれ (302) y はい・いいえ (303), por ser de lo más usado.
-- Contenido verificado (sistema こそあど: pronombres これ/それ/あれ/どれ vs
-- determinantes この/その/あの; polaridad de はい/いいえ que confirma la frase).

-- Lección 302 — Esto, eso, aquello (これ・それ・あれ) — ampliada.
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (302, 1, 'Esto, eso, aquello', 'これ・それ・あれ', 'Señala cosas con これ / それ / あれ / どれ y この / その / あの.', 12, 6, 1, '{"activities":[{"id":"u1l6g0","kind":"intro_grammar","title":"El sistema こそあど","pattern":"これ / それ / あれ / どれ","explanation":"El japonés marca la distancia con cuatro raíces: こ (cerca de mí), そ (cerca de ti), あ (lejos de ambos) y ど (pregunta). Con ellas señalas cualquier cosa.","example":{"jp":"これは本です。","reading":"これはほんです","meaning":"Esto es un libro."}},{"id":"u1l6a1","kind":"intro_vocab","word":"これ","reading":"これ","meaning":"esto (cerca de mí)","example":"これは私のかばんです。"},{"id":"u1l6a2","kind":"intro_vocab","word":"それ","reading":"それ","meaning":"eso (cerca de ti)","example":"それは何ですか。"},{"id":"u1l6a3","kind":"intro_vocab","word":"あれ","reading":"あれ","meaning":"aquello (lejos de ambos)","example":"あれは駅です。"},{"id":"u1l6a4","kind":"intro_vocab","word":"どれ","reading":"どれ","meaning":"¿cuál? (entre varios)","example":"どれがあなたのですか。"},{"id":"u1l6g1","kind":"intro_grammar","title":"これは N です","pattern":"これ / それ / あれ + は + N + です","explanation":"これ, それ y あれ van solos: sustituyen a la cosa, como un pronombre. Con は dices qué es algo.","example":{"jp":"あれは駅です。","reading":"あれはえきです","meaning":"Aquello es la estación."}},{"id":"u1l6g2","kind":"intro_grammar","title":"この・その・あの + sustantivo","pattern":"この / その / あの + N","explanation":"Cuando quieres nombrar la cosa, usa この (este~), その (ese~), あの (aquel~). Nunca van solos: siempre llevan un sustantivo detrás. «これ本» es incorrecto; lo correcto es «この本».","example":{"jp":"この本はおもしろいです。","reading":"このほんはおもしろいです","meaning":"Este libro es interesante."}},{"id":"u1l6a5","kind":"intro_vocab","word":"この","reading":"この","meaning":"este~ (+ sustantivo)","example":"この本はおもしろいです。"},{"id":"u1l6a6","kind":"intro_vocab","word":"その","reading":"その","meaning":"ese~ (+ sustantivo)","example":"そのペンをください。"},{"id":"u1l6a7","kind":"intro_vocab","word":"あの","reading":"あの","meaning":"aquel~ (+ sustantivo)","example":"あの人は先生です。"},{"id":"u1l6s1","kind":"speaking","textJp":"これは私のかばんです。","reading":"これはわたしのかばんです","meaning":"Esto es mi bolso.","voice":"Otoya"},{"id":"u1l6L1","kind":"listening","textJp":"それは何ですか。","voice":"Kyoko","prompt":"¿Qué te preguntan?","options":["¿Qué es eso?","¿Dónde está eso?","¿De quién es esto?"],"correctIndex":0,"explanation":"それ = eso (cerca de ti); 何 (なに) = qué."},{"id":"u1l6q1","kind":"quiz","prompt":"Para algo lejos de ti y de mí usas…","options":["あれ","これ","それ"],"correctIndex":0,"explanation":"あれ = aquello (lejos de ambos)."},{"id":"u1l6q2","kind":"quiz","prompt":"¿Cuál es correcto para decir «este libro»?","options":["この本","これ本","本これ"],"correctIndex":0,"explanation":"この + sustantivo. これ va solo, sin sustantivo detrás."},{"id":"u1l6w1","kind":"write_sentence","prompt":"Escribe: «Esto es un libro.»","hint":"これ + は + 本 + です","accepted":["これは本です","これは本です。","これはほんです"],"explanation":"これ = esto; 本 (ほん) = libro."},{"id":"u1l6sum","kind":"summary","learned":["これ / それ / あれ (esto / eso / aquello)","どれ (¿cuál?)","この / その / あの + sustantivo","これは N です","これ va solo; この necesita un sustantivo"]}]}');

-- Lección 303 — Sí, no y preguntas (はい・いいえ) — ampliada.
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (303, 1, 'Sí, no y preguntas', 'はい・いいえ', 'Pregunta con か y responde はい / いいえ / そうです / ちがいます.', 12, 7, 1, '{"activities":[{"id":"u1l7g1","kind":"intro_grammar","title":"〜か — hacer preguntas","pattern":"… です / ます + か","explanation":"Para preguntar, solo añade か al final. El orden de la frase no cambia: 学生です (eres estudiante) → 学生ですか (¿eres estudiante?).","example":{"jp":"学生ですか。","reading":"がくせいですか","meaning":"¿Eres estudiante?"}},{"id":"u1l7a1","kind":"intro_vocab","word":"はい","reading":"はい","meaning":"sí","example":"はい、そうです。"},{"id":"u1l7a2","kind":"intro_vocab","word":"いいえ","reading":"いいえ","meaning":"no","example":"いいえ、ちがいます。"},{"id":"u1l7g2","kind":"intro_grammar","title":"Responder: そうです / ちがいます","pattern":"はい、そうです。/ いいえ、ちがいます。","explanation":"Para confirmar dices はい、そうです (sí, así es). Para negar dices いいえ、ちがいます (no, no es así). そうです = «es así»; ちがいます = «es diferente / no es correcto».","example":{"jp":"いいえ、ちがいます。","reading":"いいえ、ちがいます","meaning":"No, no es así."}},{"id":"u1l7a3","kind":"intro_vocab","word":"そうです","reading":"そうです","meaning":"así es / correcto","example":"はい、そうです。"},{"id":"u1l7a4","kind":"intro_vocab","word":"ちがいます","reading":"ちがいます","meaning":"no es así / se equivoca","example":"いいえ、ちがいます。"},{"id":"u1l7g3","kind":"intro_grammar","title":"はい / いいえ confirman la frase","pattern":"はい = es verdad / いいえ = no es verdad","explanation":"En japonés はい y いいえ dicen si la frase es verdad; no siempre coinciden con el «sí/no» del español, sobre todo con preguntas negativas. Por eso はい、そうです confirma y いいえ、ちがいます niega lo que se preguntó.","example":{"jp":"日本人ですか。はい、そうです。","reading":"にほんじんですか。はい、そうです","meaning":"¿Eres japonés? Sí, lo soy."}},{"id":"u1l7s1","kind":"speaking","textJp":"学生ですか。はい、そうです。","reading":"がくせいですか。はい、そうです","meaning":"¿Eres estudiante? Sí, lo soy.","voice":"Otoya"},{"id":"u1l7L1","kind":"listening","textJp":"これは本ですか。","voice":"Kyoko","prompt":"¿Qué te preguntan?","options":["¿Esto es un libro?","¿Dónde está el libro?","¿De quién es el libro?"],"correctIndex":0,"explanation":"これ = esto; 本 = libro; か = pregunta."},{"id":"u1l7q1","kind":"quiz","prompt":"¿Cómo conviertes «です» en pregunta?","options":["agregar か","agregar ね","agregar を"],"correctIndex":0,"explanation":"か al final hace la pregunta."},{"id":"u1l7q2","kind":"quiz","prompt":"Para confirmar «sí, así es» dices…","options":["はい、そうです","いいえ、ちがいます","はい、ください"],"correctIndex":0,"explanation":"はい、そうです = sí, así es. ちがいます niega."},{"id":"u1l7sum","kind":"summary","learned":["〜か (hacer preguntas)","はい (sí) / いいえ (no)","はい、そうです (sí, así es)","いいえ、ちがいます (no, no es así)","はい / いいえ confirman o niegan la frase"]}]}');
